//! The standard terrain samples (brief "Decision: samples"): the day-1 set the judge uses when a
//! design names none. Each was generated by the official 26.3 server (`mctas terrain gen`, seed
//! 2, one day of game time) and cropped (`mctas terrain crop`); its world is cached under
//! `$MCTAS_HOME/terrain/worlds/<world>` (re-made by the `gen` line) for the real-game check, which
//! pastes the farm at the same spot of the same world.

/// One standard sample.
#[derive(Clone, Copy, Debug)]
pub struct Sample {
    pub name: &'static str,
    /// Its committed file (repository-relative).
    pub file: &'static str,
    pub seed: i64,
    /// The cached world it was cropped from, and the `gen` that makes it.
    pub world: &'static str,
    pub generate: &'static str,
    /// Where the spot search starts (a footprint's min column) and how far it looks.
    pub near: [i32; 2],
    pub radius: i32,
    /// What is there.
    pub about: &'static str,
}

/// The day-1 set.
pub const STANDARD: &[Sample] = &[
    Sample {
        name: "village-edge",
        file: "designs/terrain/village-edge.mcterrain",
        seed: 2,
        world: "2_-416_240_r192",
        generate: "mctas terrain gen --seed 2 --at=-416,240 --radius 192 --margin 2 --days 1 --keep",
        near: [-352, 238],
        radius: 14,
        about: "plains east of a plains village (bells at -411,70,241 and -411,70,249; 8 villagers in their beds, an iron golem, 2 cats in the crop); the spot search stays east of the village box (x > -357)",
    },
    Sample {
        name: "plains",
        file: "designs/terrain/plains.mcterrain",
        seed: 2,
        world: "2_-416_240_r192",
        generate: "mctas terrain gen --seed 2 --at=-416,240 --radius 192 --margin 2 --days 1 --keep",
        near: [-292, 222],
        radius: 14,
        about: "open plains 120 blocks east of the village (no structure within 48)",
    },
    Sample {
        name: "forest",
        file: "designs/terrain/forest.mcterrain",
        seed: 2,
        world: "2_16_0_r80",
        generate: "mctas terrain gen --seed 2 --at=16,0 --radius 80 --margin 2 --days 1 --keep",
        near: [-43, -6],
        radius: 14,
        about: "a forest west of a river, the crop 96 x 96 columns around (-16, 0) (the spot search keeps trunks out of the footprint; overhanging leaves are cleared with the site)",
    },
];

/// A standard sample by name.
pub fn sample(name: &str) -> Option<&'static Sample> {
    STANDARD.iter().find(|s| s.name == name)
}
